/*
 * A042691  Denominators of continued fraction convergents to sqrt(875).
 * https://oeis.org/A042691
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 15, u32 n <= 31, u64 n <= 60, u128 n <= 116,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Recurrence: a(n) = 240252*a(n-16) - a(n-32) for n>31,
 * denoted as the denominators of the convergents to sqrt(875).
 * The sequence is generated by iterating the continued‑fraction
 * algorithm and building the numerator denominator recurrence
 * q_k = a_k*q_{k-1} + q_{k-2} with q_{-1}=0, q_0=1.
 */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* static state for incremental computation */
    static seq_t *denoms = NULL;   /* array of denominators q_k */
    static size_t cap      = 0;    /* allocated array size */
    static size_t max_n    = 0;    /* highest index computed so far */
    static uint32_t m      = 0;    /* m_{k-1} */
    static uint32_t d      = 1;    /* d_{k-1} */
    static uint32_t a_prev = 29;   /* a_{k-1} (initial a0) */

    const uint32_t D   = 875;     /* integer under the square root */
    const uint32_t a0  = 29;      /* floor(sqrt(D)) */

    /* a(0) is always 1 */
    if (n == 0)
        return (seq_t)1;

    /* allocate and initialise storage the first time */
    if (!denoms) {
        cap    = 64;
        denoms = (seq_t*)calloc(cap, sizeof(seq_t));
        if (!denoms)
            abort();           /* allocation failure */
        denoms[0] = (seq_t)1;   /* q_0 = 1 */
        max_n    = 0;
    }

    /* compute new terms up to n if necessary */
    if ((size_t)n > max_n) {
        /* grow array if needed */
        if ((size_t)n + 1 > cap) {
            size_t new_cap = cap * 2;
            if (new_cap < (size_t)n + 1)
                new_cap = (size_t)n + 1;
            seq_t *tmp = (seq_t*)realloc(denoms, new_cap * sizeof(seq_t));
            if (!tmp)
                abort();         /* allocation failure */
            denoms = tmp;
            cap    = new_cap;
        }

        /* generate terms from max_n+1 up to n */
        for (size_t k = max_n + 1; k <= (size_t)n; ++k) {
            /* Continued fraction step */
            uint32_t m_next = d * a_prev - m;
            uint32_t d_next = (D - m_next * m_next) / d;
            uint32_t a_next = (a0 + m_next) / d_next;

            /* Denominator recurrence: q_k = a_k*q_{k-1} + q_{k-2} */
            if (k == 1) {
                denoms[1] = (seq_t)a_next * denoms[0];
            } else {
                denoms[k] = (seq_t)a_next * denoms[k-1] + denoms[k-2];
            }

            /* update state for next iteration */
            m      = m_next;
            d      = d_next;
            a_prev = a_next;
        }
        max_n = n;
    }

    return denoms[(size_t)n];
}
